    if (end === -1) throw syntaxError("Unclosed tag", position);

    const content = template.slice(contentStart, end).trim();
    cursor = end + close.length;

    if (triple) {
      output.push({
        type: "value",
        path: requirePath(content, "Interpolation", position),
        escaped: false,
